/* @autogenerated */
package net.civeira.phylax.feature.oauth.par.application.usecase.pushauthorization;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.MultivaluedHashMap;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthorizationRequestPolicy;
import net.civeira.phylax.feature.oauth.client.application.ClientAuthenticator;
import net.civeira.phylax.feature.oauth.client.application.RequestObjectVerifier;
import net.civeira.phylax.feature.oauth.client.domain.ClientAuthPolicy;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.client.domain.exception.RequestObjectException;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.feature.oauth.par.domain.ParRequest;
import net.civeira.phylax.feature.oauth.par.domain.exception.ParException;
import net.civeira.phylax.feature.oauth.par.domain.gateway.ParRequestGateway;

/**
 * Pushes an authorization request and returns a {@code request_uri} — RFC 9126, tasks 0.14 and 2.3.
 *
 * <ul>
 * <li>The client authenticates with its registered method: secret, or {@code client_id} alone for a
 * public client.</li>
 * <li>The {@code client_id} of the request, if sent, must be the authenticated client; a
 * {@code request_uri} inside a push is rejected (§2.1).</li>
 * <li>The request is validated now, as the authorization endpoint would: registered redirect,
 * response type, audiences and PKCE. An invalid push never gets a {@code request_uri}.</li>
 * <li>A signed request object ({@code request}) replaces the other parameters, once verified (task
 * 3.3).</li>
 * <li>Only authorization parameters are stored, never client credentials.</li>
 * </ul>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class PushAuthorizationUsecase {

  /**
   * Client credentials: authenticate the push, never stored with it (task 0.11).
   */
  private static final Set<String> CLIENT_CREDENTIALS =
      Set.of("client_secret", "client_assertion", "client_assertion_type");

  private final ClientAuthenticator clientAuthenticator;
  private final ClientStoreGateway clients;
  private final ParRequestGateway gateway;
  private final RequestObjectVerifier requestObjects;

  public PushAuthorizationResult push(PushAuthorizationParams params) {
    ClientDetails client =
        clientAuthenticator.authenticate(params.getTenant(), params.getCredentials(),
            ClientAuthPolicy.REGISTERED_METHOD).orElseThrow(ParException::invalidClient);

    Map<String, String> authParams = new LinkedHashMap<>(params.getAuthParams());
    authParams.keySet().removeAll(CLIENT_CREDENTIALS);
    if (authParams.containsKey("request_uri")) {
      throw ParException.invalidRequest("request_uri is not allowed in a pushed request");
    }
    if (authParams.containsKey("request")) {
      // A signed request object inside the push: only its claims count (RFC 9126 §3).
      String outer = authParams.get("client_id");
      if (outer != null && !outer.equals(client.getClientId())) {
        throw ParException.invalidRequest("client_id does not match the authenticated client");
      }
      try {
        authParams = new LinkedHashMap<>(requestObjects.verify(params.getTenant(),
            params.getIssuer(), client, authParams.get("request")));
      } catch (RequestObjectException ex) {
        throw ParException.of(ex.getErrorCode(), ex.getMessage());
      }
    }
    String clientId = authParams.getOrDefault("client_id", client.getClientId());
    if (!client.getClientId().equals(clientId)) {
      throw ParException.invalidRequest("client_id does not match the authenticated client");
    }
    authParams.put("client_id", clientId);
    String redirect = authParams.getOrDefault("redirect_uri", "");
    if (redirect.isBlank()) {
      throw ParException.invalidRequest("redirect_uri is required");
    }
    ClientDetails authorizing = clients.loadForAuthorization(params.getTenant(), clientId, redirect)
        .orElseThrow(() -> ParException.invalidRequest("redirect_uri is not registered"));

    MultivaluedHashMap<String, String> asQuery = new MultivaluedHashMap<>();
    authParams.forEach(asQuery::putSingle);
    AuthRequest request =
        AuthRequest.fromParams(params.getTenant(), asQuery, Locale.getDefault()).asPushed();
    AuthorizationRequestPolicy.violation(request, authorizing).ifPresent(violation -> {
      throw ParException.of(violation.error(), violation.description());
    });

    ParRequest parRequest = ParRequest.create(params.getTenant(), clientId, authParams);
    gateway.store(parRequest);

    return new PushAuthorizationResult(parRequest.getRequestUri(), parRequest.expiresInSeconds());
  }
}
